from lib import runs
from content_a import note, figcap
import resnums as N
from resnums import f, sg, ref, P1, P2, P3, P4, S, TK, CM, M13
import numpy as np, pandas as pd
CTXN = {"novpn": "Non-VPN", "vpn": "VPN"}
MN = {"RF": "Random Forest", "XGB": "XGBoost"}
FIG = N.RES.parent / "figures"

def baseline(D):
    B = lambda m, c: P1[f"base_{m}_{c}"]
    D.h1("V. BASELINE CLASSIFICATION RESULTS")
    D.p(f"Table IV and Fig. 3 report results on the primary test partitions. Both ensembles do well in both contexts, with XGBoost slightly ahead. Without a VPN, XGBoost reaches {f(B('XGB','novpn')['acc'],4)} accuracy and {f(B('XGB','novpn')['f1'],4)} macro F1, and Random Forest {f(B('RF','novpn')['acc'],4)} and {f(B('RF','novpn')['f1'],4)}. With a VPN, XGBoost drops to {f(B('XGB','vpn')['acc'],4)} and {f(B('XGB','vpn')['f1'],4)} and Random Forest to {f(B('RF','vpn')['acc'],4)} and {f(B('RF','vpn')['f1'],4)}, a macro F1 loss of {f(B('XGB','novpn')['f1']-B('XGB','vpn')['f1'],4)} and {f(B('RF','novpn')['f1']-B('RF','vpn')['f1'],4)}. We prefer macro F1 because class mixes differ between contexts and BROWSING and VOIP fill over half of each test partition.")
    rx, rv = B("XGB", "novpn")["recall_per_class"], B("XGB", "vpn")["recall_per_class"]
    D.p(f"Per class, VOIP is hardly affected, with recall above 0.99 in both contexts, and BROWSING stays at 0.93 or above. CHAT, FT, MAIL and P2P pay most of the cost: with XGBoost, MAIL recall falls from {f(rx[3])} to {f(rv[3])}, P2P from {f(rx[4])} to {f(rv[4])}, CHAT from {f(rx[1])} to {f(rv[1])} and FT from {f(rx[2])} to {f(rv[2])}. STREAMING goes the other way, from {f(rx[5])} to {f(rv[5])} for XGBoost and from {f(B('RF','novpn')['recall_per_class'][5])} to {f(B('RF','vpn')['recall_per_class'][5])} for Random Forest. We do not read this as evidence that a VPN makes streaming easier to identify; the captured streaming sessions, or the classes streaming is confused with, may differ between contexts, and a flow-level dataset cannot separate these explanations.")
    rows = [["Context", "Model", "Acc.", "Macro F1", "BROW", "CHAT", "FT", "MAIL", "P2P", "STRM", "VOIP"]]
    for c in ("novpn", "vpn"):
        for m in ("RF", "XGB"):
            b = B(m, c); rows.append([CTXN[c], m, f(b["acc"], 4), f(b["f1"], 4)] + [f(x) for x in b["recall_per_class"]])
    D.table("Baseline performance and per-class recall on the primary test partitions", [1000, 700, 780, 900] + [806] * 7, rows,
            note="BROW = BROWSING, STRM = STREAMING. Test support (Non-VPN / VPN): BROWSING 500/500, CHAT 178/232, FT 171/377, MAIL 48/86, P2P 188/133, STREAMING 90/95, VOIP 564/453.")
    D.figure(FIG / "fig3_baseline.png", "Baseline performance on the primary test partitions. (a) Macro F1 (bars) and accuracy (diamonds). (b) Recall per class. Under VPN the ensembles lose 0.050 (XGBoost) and 0.064 (Random Forest) macro F1, mostly in CHAT, FT, MAIL and P2P.")

def consistency(D, O):
    D.h1("VI. EXPLANATION CONSISTENCY")
    D.h2("A. Global Rankings in Each Context")
    pr = {(m, c): P1[f"prim_{m}_{c}"] for m in ("RF", "XGB") for c in ("novpn", "vpn")}
    t5 = {k: list(v["share"].keys())[:5] for k, v in pr.items()}
    D.p(f"The primary importance profiles are given in Table V and Fig. 4. Without a VPN, the five most important features account for {N.pct(pr[('RF','novpn')]['top5_share'])}% of total importance in Random Forest and {N.pct(pr[('XGB','novpn')]['top5_share'])}% in XGBoost; with a VPN, {N.pct(pr[('RF','vpn')]['top5_share'])}% and {N.pct(pr[('XGB','vpn')]['top5_share'])}%. The top ten take between {N.pct(min(v['top10_share'] for v in pr.values()))}% and {N.pct(max(v['top10_share'] for v in pr.values()))}%. These are normalised sums of mean absolute SHAP, not shares of explained variance.")
    D.p(f"On Non-VPN data the top five for Random Forest are {', '.join(t5[('RF','novpn')][:4])} and {t5[('RF','novpn')][4]}; on VPN data they are {', '.join(t5[('RF','vpn')][:4])} and {t5[('RF','vpn')][4]}. XGBoost puts {', '.join(t5[('XGB','novpn')][:4])} and {t5[('XGB','novpn')][4]} on top for Non-VPN, and {', '.join(t5[('XGB','vpn')][:4])} and {t5[('XGB','vpn')][4]} for VPN. The two models agree with each other at Spearman {f(P1['cross_model']['novpn'])} on Non-VPN and {f(P1['cross_model']['vpn'])} on VPN.")
    rows = [["Rank", "RF Non-VPN", "RF VPN", "XGB Non-VPN", "XGB VPN"]]
    L = {k: list(v["share"].items()) for k, v in pr.items()}
    for r in range(10):
        rows.append([str(r + 1)] + [f"{L[(m, c)][r][0]} ({100 * L[(m, c)][r][1]:.2f})" for m in ("RF", "XGB") for c in ("novpn", "vpn")])
    D.table("Ten leading features of the primary TreeSHAP rankings, with normalised importance shares (%)", [600, 2106, 2106, 2107, 2107], rows,
            note="Shares are percentages of total mean absolute SHAP, averaged over test records and model output classes; within each model and context they sum to 100% over all 23 features. Fig. 4 shows all 23 shares.")
    D.figure(FIG / "fig4_shares.png", "Primary TreeSHAP importance shares, Random Forest left and XGBoost right. Features are ordered by Non-VPN importance so that the two contexts can be compared directly.")
    D.h2("B. Cross-Context Agreement on the Primary Split")
    cr, cx = P1["cross_RF"], P1["cross_XGB"]
    D.p(f"For Random Forest, Spearman ρ between the Non-VPN and VPN rankings is {f(cr['rho'],4)} and Kendall τ_{{b}} is {f(cr['tau'],4)}; for XGBoost, ρ = {f(cx['rho'],4)} and τ_{{b}} = {f(cx['tau'],4)} (Table VI). The whole-ranking correlations look high, yet each model keeps only three of its top five features (κ_{{5}} = {f(cr['kappa5'],2)}), and RBO is {f(cr['rbo'])} for Random Forest and {f(cx['rbo'])} for XGBoost. The L1 distance between share vectors is {f(cr['l1'])} and {f(cx['l1'])}, so about a sixth of the total importance changes hands, and the mean absolute rank displacement is {f(cr['disp'],2)} and {f(cx['disp'],2)} positions. At ten features the overlap is {cr['top10']} of 10 for Random Forest (κ_{{10}} = {f(cr['kappa10'],2)}) and {cx['top10']} of 10 for XGBoost (κ_{{10}} = {f(cx['kappa10'],2)}). Weighting true classes equally changes the within-context rankings little (ρ between weighted and unweighted rankings {f(min(P1['w_vs_unw_RF']+P1['w_vs_unw_XGB']))}–{f(max(P1['w_vs_unw_RF']+P1['w_vs_unw_XGB']))}) and leaves the cross-context values at a similar level.")
    rk = {m: P1[f"ranks_{m}"] for m in ("RF", "XGB")}
    mv = lambda m, ft: f"{ft} ({rk[m]['novpn'][ft]} \u2192 {rk[m]['vpn'][ft]})"
    D.p(f"Fig. 5 follows single features (Non-VPN rank \u2192 VPN rank). In Random Forest, {mv('RF','min_fiat')} and {mv('RF','min_biat')} move up, while {mv('RF','total_biat')}, {mv('RF','total_fiat')} and {mv('RF','mean_fiat')} move down. In XGBoost, {mv('XGB','mean_biat')}, {mv('XGB','min_biat')} and {mv('XGB','max_flowiat')} rise, whereas {mv('XGB','total_biat')} and {mv('XGB','flowPktsPerSecond')} fall. Some directional features rise while others in the same family fall, so a description in terms of forward versus backward misses most of what happens.")
    c0, c1 = P1["corr_novpn"], P1["corr_vpn"]
    D.p(f"Several of the movers are correlated with other features, which matters for how SHAP shares out credit (Fig. 6). Some pairs are close to redundant: duration correlates with total_fiat and total_biat at Spearman {f(min(c0['duration|total_biat'],c1['duration|total_biat'],c0['duration|total_fiat'],c1['duration|total_fiat']),2)}–{f(max(c0['duration|total_biat'],c1['duration|total_biat'],c0['duration|total_fiat'],c1['duration|total_fiat']),2)}, total_fiat with total_biat at {f(c0['total_fiat|total_biat'],2)}–{f(c1['total_fiat|total_biat'],2)}, and the two throughput features at {f(c0['flowBytesPerSecond|flowPktsPerSecond'],2)}. A model can move credit within such a group with little change in its predictions, which fits the fall of total_biat and total_fiat. The three minimum IATs are less tightly linked. Spearman correlation is {f(c0['min_fiat|min_biat'],2)} (Non-VPN) and {f(c1['min_fiat|min_biat'],2)} (VPN) between min_fiat and min_biat, {f(c0['min_fiat|min_flowiat'],2)} and {f(c1['min_fiat|min_flowiat'],2)} between min_fiat and min_flowiat, and {f(c0['min_biat|min_flowiat'],2)} and {f(c1['min_biat|min_flowiat'],2)} between min_biat and min_flowiat. By construction min_flowiat never exceeds the smaller of min_fiat and min_biat, but it equals that minimum in only {N.pct(P1['minflow_eq_novpn'],0)}% of Non-VPN and {N.pct(P1['minflow_eq_vpn'],0)}% of VPN training flows, because interleaved forward and backward packets create shorter gaps. Moderate and non-monotone dependence of this kind can still redistribute SHAP credit, so Section VI-E tests the minimum-IAT shifts by retraining.")
    rows = [["Model", "Spearman ρ", "Kendall τ_{b}", "RBO", "L1", "Top-5 (κ_{5})", "Top-10 (κ_{10})", "Rank disp."]]
    for lab, d in (("RF", cr), ("XGB", cx), ("RF, classes weighted", P1["cross_RF_weighted"]), ("XGB, classes weighted", P1["cross_XGB_weighted"])):
        rows.append([lab, f(d["rho"], 4), f(d["tau"], 4), f(d["rbo"]), f(d["l1"]), f"{d['top5']}/5 ({f(d['kappa5'],2)})", f"{d['top10']}/10 ({f(d['kappa10'],2)})", f(d["disp"], 2) if "disp" in d else "—"])
    D.table("Cross-context ranking agreement of the primary fits", [1900, 1000, 1000, 800, 800, 1250, 1300, 976], rows,
            note="Single fits on the primary partitions, explained on the full test partitions. RBO is extrapolated rank-biased overlap with p = 0.9; L1 is the distance between normalised share vectors (0 to 2); κ_{k} is the chance-corrected Top-k overlap of (5); rank disp. is the mean absolute rank displacement. Class-weighted rows give every true class the same weight in (2).")
    D.figure(FIG / "fig5_ranks.png", "Feature ranks under Non-VPN and VPN on the primary split, for Random Forest (left) and XGBoost (right). Each line joins the two ranks of a feature; dotted lines mark the Top-5 and Top-10 cut-offs. Features that move by three or more ranks are drawn in colour.")
    D.add(O[136]); D.fig_n += 1
    figcap(D, D.fig_n, "Spearman correlations between the 23 features on the training partition of (a) Non-VPN and (b) VPN flows. Values are printed for the three minimum IAT features (min_fiat, min_biat, min_flowiat). Duration and the total IATs, the two throughput features, and the maximum, active and idle statistics form tightly correlated blocks.")

    D.h2("C. Within-Context References and Permutation Null")
    g = lambda m, d, k="rho_gap", s="mean": ref(m, d, k, s)
    D.p(f"Table VII and Fig. 7 set the cross-context agreement against the three reference designs. With flow-level random halves, within-context agreement is high ({f(g('XGB','random','rho_wnv'))} and {f(g('XGB','random','rho_wvpn'))} for XGBoost on Non-VPN and VPN, {f(g('RF','random','rho_wnv'))} and {f(g('RF','random','rho_wvpn'))} for Random Forest) and cross-context agreement is lower ({f(g('XGB','random','rho_cross'))} and {f(g('RF','random','rho_cross'))}). The gap is {f(g('XGB','random'))} for XGBoost (SD {f(g('XGB','random','rho_gap','sd'))}, range {f(g('XGB','random','rho_gap','min'))} to {f(g('XGB','random','rho_gap','max'))} over 11 repeats) and {f(g('RF','random'))} for Random Forest (SD {f(g('RF','random','rho_gap','sd'))}, range {f(g('RF','random','rho_gap','min'))} to {f(g('RF','random','rho_gap','max'))}). Because each repeat now redraws the 80/20 partition, these spreads are two to four times larger than in the previous version, which reused one partition. The gap appears at the top of the list as well: random halves of one context share {f(g('XGB','random','top5_wnv'),1)}–{f(g('XGB','random','top5_wvpn'),1)} of five leading XGBoost features against {f(g('XGB','random','top5_cross'),1)} across contexts, and the RBO gap is {f(g('XGB','random','rbo_gap'))} for XGBoost and {f(g('RF','random','rbo_gap'))} for Random Forest. With true classes weighted equally the ρ gaps are {f(g('XGB','random','rho_w_gap'))} and {f(g('RF','random','rho_w_gap'))}.")
    D.p(f"The permutation null shows that this gap is not produced by the half-split procedure or by the class-mix difference alone. When flows are reassigned at random between two pseudo-contexts that keep the Non-VPN and VPN class mixes, Δ is {sg(g('XGB','null'))} for XGBoost (range {f(g('XGB','null','rho_gap','min'))} to {f(g('XGB','null','rho_gap','max'))}) and {sg(g('RF','null'))} for Random Forest (range {f(g('RF','null','rho_gap','min'))} to {f(g('RF','null','rho_gap','max'))}).")
    D.p(f"The cluster-grouped references change the picture. Keeping clusters of about ten similar flows on one side lowers within-context agreement (XGBoost {f(g('XGB','grouped10','rho_wnv'))} and {f(g('XGB','grouped10','rho_wvpn'))}, Random Forest {f(g('RF','grouped10','rho_wnv'))} and {f(g('RF','grouped10','rho_wvpn'))}) while cross-context agreement barely moves, and Δ shrinks to {f(g('XGB','grouped10'))} and {f(g('RF','grouped10'))}. With about 35 flows per cluster Δ is {f(g('XGB','grouped35'))} and {f(g('RF','grouped35'))}, and with about 140 it is {sg(g('XGB','grouped'))} and {sg(g('RF','grouped'))}. The coarsest grouping is harsh: its half-models reach only {f(min(g(m,'grouped',k) for m in ('RF','XGB') for k in ('f1_nv','f1_vpn')),2)}–{f(max(g(m,'grouped',k) for m in ('RF','XGB') for k in ('f1_nv','f1_vpn')),2)} macro F1, and Random Forest rankings become unstable in every comparison. But even the finest grouping, which separates only very close neighbours, removes {f(100*(1-g('XGB','grouped10')/g('XGB','random')),0)}% of the XGBoost gap and {f(100*(1-g('RF','grouped10')/g('RF','random')),0)}% of the Random Forest gap.")
    D.p("Taken together, cross-context rankings disagree more than random halves of one context do, and this excess is not an artefact of the procedure or of class mix. Once related flows are kept together, however, most of the excess goes: with clusters of about 35 flows or more, within-context disagreement is about as large as cross-context disagreement. On this benchmark the cross-context difference cannot be separated from between-session variation, and the earlier reading of the random-split gap as a context effect is not supported.")
    rows = [["Model / design", "Half-model F1\nNV / VPN", "Within\nNV", "Within\nVPN", "Cross", "Δρ mean (SD)\nrange", "ΔRBO", "ΔTop-5", "Δρ classes\nweighted"]]
    DES = [("random", "Random halves"), ("grouped10", "Grouped, ~10 per cluster"), ("grouped35", "Grouped, ~35 per cluster"), ("grouped", "Grouped, ~140 per cluster"), ("null", "Permutation null")]
    for m in ("XGB", "RF"):
        rows.append({"section": f"{MN[m]} (11 repeats per design)"})
        for d, lab in DES:
            rows.append([lab, f"{f(g(m,d,'f1_nv'),3)} / {f(g(m,d,'f1_vpn'),3)}", f(g(m, d, "rho_wnv")), f(g(m, d, "rho_wvpn")), f(g(m, d, "rho_cross")),
                         f"{sg(g(m,d))} ({f(g(m,d,'rho_gap','sd'))})\n{f(g(m,d,'rho_gap','min'))} to {f(g(m,d,'rho_gap','max'))}", sg(g(m, d, "rbo_gap")), sg(g(m, d, "top5_gap"), 2), sg(g(m, d, "rho_w_gap"))])
    D.table("Within- and cross-context Spearman agreement under three reference designs", [1900, 1200, 700, 700, 700, 1450, 800, 800, 776], rows,
            note="Every repeat redraws the stratified 80/20 partition of each context. Within values compare the two halves of one context; cross values average the four Non-VPN-half versus VPN-half pairs of the same repeat. Δ is the mean within value minus the cross value, averaged over repeats; SD and range describe its spread over repeats and are not standard errors. Half-model F1 is macro F1 on the repeat's test partition. Grouped designs keep whole k-means clusters (fitted within class on log(x + 2)-standardised features) in one half. The null pools flows within class across contexts and reassigns them at random to pseudo-contexts with the original class counts. Random Forest half-models are explained on 800 test records per repeat.")
    D.figure(FIG / "fig7_references.png", "Within-context (green) and cross-context (purple) Spearman agreement for each repeat of the five reference designs, with means as bars. The gap Δ under each design is given below its label. Values are dependent across repeats and are shown descriptively.")

    D.h2("D. Class Composition")
    cm = CM[CM.mix != "nat_vs_swap"].groupby(["model", "ctx", "mix"])[["f1", "rho_same", "rho_other", "rbo_other"]].mean()
    nvs = CM[CM.mix == "nat_vs_swap"].groupby(["model", "ctx"])["rho_same"].mean()
    dlt = {(m, c): cm.loc[(m, c, "swapped"), "rho_other"] - cm.loc[(m, c, "natural"), "rho_other"] for m in ("RF", "XGB") for c in ("novpn", "vpn")}
    D.p(f"Table VIII reports the class-mix swap. Resampling a context to the other context's class mix changes its own ranking only a little (ρ between natural-mix and swapped-mix models {f(nvs.min())}–{f(nvs.max())}) and does not bring it closer to the other context. Agreement with the other context's primary ranking changes by {', '.join(sg(dlt[(m,c)]) for m in ('XGB','RF') for c in ('novpn','vpn'))} for XGBoost (Non-VPN, VPN) and Random Forest (Non-VPN, VPN), against a cross-context gap of 0.13–0.19 under random halves. The permutation null of Section VI-C, which keeps both class mixes and removes everything else, gives no XGBoost gap and a Random Forest gap of {f(ref('RF','null','rho_gap'),2)}. Class-weighted importance leaves the gaps in place (Table VII).")
    mm = M13.groupby("kind")["rho"].mean()
    D.p(f"Class-matched training gives the same answer once it is compared with a reference of its own size. With 1,330 training flows per model, two disjoint natural-mix draws of one context agree at ρ = {f(mm['within_nat_novpn'])} (Non-VPN) and {f(mm['within_nat_vpn'])} (VPN); natural-mix draws of different contexts agree at {f(mm['cross_nat'])} and class-matched draws at {f(mm['cross_mat'])}. The rise in cross-context ρ under matching that the previous version reported (to about 0.85) is therefore a property of small training sets, which agree more with everything, and not a sign that class mix explains the gap: at this size the within-minus-cross gap is still {f((mm['within_nat_novpn']+mm['within_nat_vpn'])/2-mm['cross_nat'],2)} with natural mixes. Two matched draws of Non-VPN share all 190 MAIL flows, so their agreement ({f(mm['within_mat_novpn'])}) is not used as a reference.")
    rows = [["Model / context", "Training mix", "Macro F1", "ρ with own\nprimary ranking", "ρ with other\ncontext's ranking", "RBO with other\ncontext's ranking"]]
    for m, nr in (("XGB", 5), ("RF", 3)):
        for c in ("novpn", "vpn"):
            for mix, lab in (("natural", "Own"), ("swapped", "Other context's")):
                r = cm.loc[(m, c, mix)]
                rows.append([f"{m} / {CTXN[c]} ({nr} draws)", lab, f(r["f1"]), f(r["rho_same"]), f(r["rho_other"]), f(r["rbo_other"])])
    D.table("Class-mix swap: models trained on 3,400 flows with their own or the other context's class proportions", [2100, 1500, 1100, 1450, 1450, 1426], rows,
            note="Means over draws. Models are explained on their own context's test partition and compared with the primary rankings of Section VI-A (Random Forest on a fixed 800-record test sample). If class mix drove the cross-context disagreement, the swapped rows would show higher agreement with the other context than the own-mix rows.")
    min_iat(D)
    D.h2("F. Why VPN Rankings Look Steadier")
    D.p(f"Under flow-level random halves, VPN rankings agree more with each other than Non-VPN rankings do (XGBoost {f(ref('XGB','random','rho_wvpn'))} against {f(ref('XGB','random','rho_wnv'))}; Random Forest {f(ref('RF','random','rho_wvpn'))} against {f(ref('RF','random','rho_wnv'))}), although VPN accuracy is lower. The pattern does not hold under grouping. With clusters of about 140 flows, within-VPN agreement falls below within-Non-VPN agreement for both models ({f(ref('XGB','grouped','rho_wvpn'))} against {f(ref('XGB','grouped','rho_wnv'))}, and {f(ref('RF','grouped','rho_wvpn'))} against {f(ref('RF','grouped','rho_wnv'))}), and Random Forest already shows the reversal at about ten flows per cluster. The apparent steadiness of VPN explanations therefore seems to come from redundancy among related VPN flows, which random halves share, more than from any stability of the VPN explanation itself. A second, smaller contributor may be class balance: the rarest VPN class holds 4.6% of training flows against 2.7% for Non-VPN MAIL, and rare classes produce noisier attributions. The data do not allow a firmer explanation.")

def min_iat(D):
    D.h2("E. The Minimum Inter-Arrival-Time Shifts")
    dr = lambda m, c, x: P4[f"drop_{m}_{c}_{x}"]
    D.p("The features that move most between contexts are the three minimum IATs. Because they are moderately correlated, a SHAP shift among them could reflect credit passing between features that the model treats as substitutes. We tested this in three ways (Table IX).")
    g = {(m, c): dr(m, c, "all3")["df1"] for m in ("RF", "XGB") for c in ("novpn", "vpn")}
    one = [dr(m, c, x)["df1"] for m in ("RF", "XGB") for c in ("novpn", "vpn") for x in ("min_fiat", "min_biat", "min_flowiat")]
    D.p(f"*Drop-one and grouped retraining.* Removing any one of the three and retraining changes macro F1 by {sg(max(one))} to {sg(min(one))}, whereas removing all three costs {f(-max(g.values()))}–{f(-min(g.values()))}. As a block, the minimum IATs carry information the other features do not; individually they are partly interchangeable. Credit does move among them when one is removed. In the VPN Random Forest, dropping min_fiat raises the shares of min_flowiat and min_biat by {f(dr('RF','vpn','min_fiat')['share_others']['min_flowiat']-dr('RF','vpn','min_fiat')['base_share']['min_flowiat'],1)} and {f(dr('RF','vpn','min_fiat')['share_others']['min_biat']-dr('RF','vpn','min_fiat')['base_share']['min_biat'],1)} percentage points, and in the Non-VPN XGBoost model dropping min_flowiat moves min_biat from rank {dr('XGB','novpn','min_flowiat')['base_rank']['min_biat']} to {dr('XGB','novpn','min_flowiat')['rank_others']['min_biat']}. Part of the cross-context shift among the three can therefore be redistribution of credit. With all three removed, cross-context ρ over the remaining 20 features is {f(P4['drop_all3_cross_RF']['rho'])} for Random Forest and {f(P4['drop_all3_cross_XGB']['rho'])} for XGBoost, so the disagreement is not confined to them.")
    pi = lambda m, c: P4[f"pi_{m}_{c}"]
    D.p(f"*Permutation importance.* Permutation importance on the test partitions, measured as the loss of macro F1, does not split credit by Shapley rules. Under it, min_fiat and min_biat already rank high without a VPN ({pi('RF','novpn')['rank_min']['min_fiat']} and {pi('RF','novpn')['rank_min']['min_biat']} for Random Forest, {pi('XGB','novpn')['rank_min']['min_fiat']} and {pi('XGB','novpn')['rank_min']['min_biat']} for XGBoost) and move up by only one or two places with one ({pi('RF','vpn')['rank_min']['min_fiat']} and {pi('RF','vpn')['rank_min']['min_biat']}; {pi('XGB','vpn')['rank_min']['min_fiat']} and {pi('XGB','vpn')['rank_min']['min_biat']}). The large SHAP rises of min_fiat (Random Forest, {rk('RF','novpn','min_fiat')} to {rk('RF','vpn','min_fiat')}) and min_biat (Random Forest {rk('RF','novpn','min_biat')} to {rk('RF','vpn','min_biat')}, XGBoost {rk('XGB','novpn','min_biat')} to {rk('XGB','vpn','min_biat')}) are therefore not reproduced by this measure. Without a VPN the directional minima matter for the predictions, but TreeSHAP assigns much of their credit to other, correlated features. Permuting the three minima jointly costs {f(pi('RF','novpn')['grouped']['min-IAT trio'])} and {f(pi('RF','vpn')['grouped']['min-IAT trio'])} macro F1 for Random Forest and {f(pi('XGB','novpn')['grouped']['min-IAT trio'])} and {f(pi('XGB','vpn')['grouped']['min-IAT trio'])} for XGBoost, and cross-context agreement of the permutation rankings is \u03c1 = {f(P4['pi_cross_RF']['rho'])} (Random Forest) and {f(P4['pi_cross_XGB']['rho'])} (XGBoost).")
    b = lambda m, c: P4[f"below_{m}_{c}"]
    D.p(f"*Entries below −1.* All entries below −1 in the data are negative min_flowiat values: {P1['audit_novpn']['below_m1_entries']} Non-VPN training flows ({P1['audit_novpn']['below_m1_by_class'][2]} of them FT) and {P1['audit_vpn']['below_m1_entries']} VPN training flows ({P1['audit_vpn']['below_m1_by_class'][4]} P2P). A negative gap between consecutive packets is physically impossible and most likely a timestamp artefact. The test partitions hold {b('XGB','novpn')['n_test_below']} and {b('XGB','vpn')['n_test_below']} such flows, which carry {N.pct(b('RF','novpn')['attr_share_minflowiat'])}% and {N.pct(b('RF','vpn')['attr_share_minflowiat'])}% of the min_flowiat attribution of the Random Forest models ({N.pct(b('XGB','novpn')['attr_share_minflowiat'])}% and {N.pct(b('XGB','vpn')['attr_share_minflowiat'])}% for XGBoost). Removing them from training leaves the rankings almost unchanged (ρ with the primary ranking {f(min(b(m,c)['rho_vs_primary'] for m in ('RF','XGB') for c in ('novpn','vpn')))}–{f(max(b(m,c)['rho_vs_primary'] for m in ('RF','XGB') for c in ('novpn','vpn')))}), so they do not drive the minimum-IAT shifts.")
    D.p("In sum, the minimum IATs matter as a group in both contexts. Their large rise in the SHAP rankings under VPN is only partly a change in what the models rely on: permutation importance shows a much smaller shift, and retraining shows that credit moves among the three when one is removed. A substantial part of the most visible cross-context difference in the SHAP rankings is therefore a difference in how Shapley credit is split among correlated timing features, not in which information the models use. The remaining shift could reflect tunnelling, but the present data cannot separate that from differences between capture sessions.")
    rows = [["Model / context", "SHAP ranks\nfiat / biat / flowiat", "ΔF1 drop\nmin_fiat", "ΔF1 drop\nmin_biat", "ΔF1 drop\nmin_flowiat", "ΔF1 drop\nall three", "Permutation ranks\nfiat / biat / flowiat", "ΔF1 joint\npermutation"]]
    for m in ("RF", "XGB"):
        for c in ("novpn", "vpn"):
            br = P1[f"ranks_{m}"][c]; p = pi(m, c)["rank_min"]
            rows.append([f"{m} / {CTXN[c]}", f"{br['min_fiat']} / {br['min_biat']} / {br['min_flowiat']}"] + [sg(dr(m, c, x)["df1"]) for x in ("min_fiat", "min_biat", "min_flowiat", "all3")]
                        + [f"{p['min_fiat']} / {p['min_biat']} / {p['min_flowiat']}", sg(-pi(m, c)["grouped"]["min-IAT trio"])])
    D.table("Checks on the minimum-IAT features: retraining without them and permutation importance", [1380, 1250, 880, 880, 1120, 880, 1376, 1240], rows,
            note="SHAP ranks are those of the primary models on the full test partitions (Table V, Fig. 5); share changes after dropping a feature are computed on a fixed 800-record test sample for Random Forest. ΔF1 is the change in macro F1 after retraining without the listed feature(s), or after permuting all three minima together in the test partition (mean of 10 permutations). Permutation importance uses macro F1 and 10 repeats.")

def rk(m, c, ft):
    return P1[f'ranks_{m}'][c][ft]

def pi_sentence():
    r = {(m, c): P4[f"pi_{m}_{c}"]["rank_min"] for m in ("RF", "XGB") for c in ("novpn", "vpn")}
    up = [m for m in ("RF", "XGB") if r[(m, "vpn")]["min_fiat"] + r[(m, "vpn")]["min_biat"] < r[(m, "novpn")]["min_fiat"] + r[(m, "novpn")]["min_biat"]]
    if len(up) == 2: return "Under both models the directional minima therefore rank higher with a VPN than without, as they do under SHAP."
    if len(up) == 1: return f"The directional minima rank higher with a VPN under {MN[up[0]]} only, so the SHAP pattern is only partly reproduced by this second measure."
    return "Unlike SHAP, permutation importance does not rank the directional minima higher with a VPN."

def families(D):
    D.h1("VII. AGGREGATED FEATURE-FAMILY IMPORTANCE")
    fs = {(m, c): P1[f"prim_{m}_{c}"]["family_share"] for m in ("RF", "XGB") for c in ("novpn", "vpn")}
    D.p(f"Under the six semantic families, directional IAT comes first, flow IAT second and throughput third in every model and context on the primary fits. From Non-VPN to VPN the directional share of Random Forest grows from {fs[('RF','novpn')]['Directional IAT']:.2f}% to {fs[('RF','vpn')]['Directional IAT']:.2f}% and that of XGBoost from {fs[('XGB','novpn')]['Directional IAT']:.2f}% to {fs[('XGB','vpn')]['Directional IAT']:.2f}%; flow IAT moves from {fs[('RF','novpn')]['Flow IAT']:.2f}% to {fs[('RF','vpn')]['Flow IAT']:.2f}% and from {fs[('XGB','novpn')]['Flow IAT']:.2f}% to {fs[('XGB','vpn')]['Flow IAT']:.2f}%. Table X compares four aggregation rules on the primary fits and in the half-split repeats.")
    alt = {(m, c): N.fam(N.prim(m, c), N.ALT) for m in ("RF", "XGB") for c in ("novpn", "vpn")}
    alt = {k: v / v.sum() * 100 for k, v in alt.items()}
    lead = {k: v.idxmax() for k, v in alt.items()}
    D.p(f"The steadiness of the six-family summary depends on the grouping. Summed over six families, the half-split gap is {f(ref('RF','random','fam_gap'))} for Random Forest and {f(ref('XGB','random','fam_gap'))} for XGBoost, smaller than the feature-level gaps, but six ranks are coarse (swapping one adjacent pair changes ρ by about 0.06), and the eight-member directional family tops every ranking partly by size. Ranked by mean importance per member, the gaps are {f(ref('RF','random','fam_mean_gap'))} and {f(ref('XGB','random','fam_mean_gap'))}, and throughput or duration leads. Moving total_fiat and total_biat into a duration-and-totals family gives gaps of {f(ref('RF','random','fam_alt_gap'))} and {f(ref('XGB','random','fam_alt_gap'))}, and it changes the primary summary: the shares of the three leading families on Non-VPN data are then within {f(max(alt[('RF','novpn')].nlargest(3))-min(alt[('RF','novpn')].nlargest(3)),1)} percentage points of each other for Random Forest, and for XGBoost the leading family is {lead[('XGB','novpn')]} without a VPN and {lead[('XGB','vpn')]} with one. The eight data-driven clusters give gaps of {f(ref('RF','random','clust_gap'))} and {f(ref('XGB','random','clust_gap'))}, larger than the semantic-family gaps, consistent with the three minimum IATs staying in separate clusters. With cluster-grouped halves of about ten flows the summed-family gap is {sg(ref('RF','grouped10','fam_gap'))} for Random Forest and {sg(ref('XGB','grouped10','fam_gap'))} for XGBoost. Family summaries are therefore useful only together with their grouping rule and family sizes.")
    rows = [["Model / aggregation", "Primary ρ", "Within NV", "Within VPN", "Cross", "Δ random\nhalves", "Δ grouped\n~10 per cluster"]]
    RULES = [("Six families, summed", "fam", N.FAMILIES, False), ("Six families, mean per member", "fam_mean", N.FAMILIES, True),
             ("Totals moved to duration, summed", "fam_alt", N.ALT, False), ("Eight correlation clusters, summed", "clust", N.CLUST, False)]
    for m in ("RF", "XGB"):
        for lab, key, fams, mean in RULES:
            rows.append([f"{m} / {lab}", f(N.fam_rho(m, fams, mean)), f(ref(m, "random", key + "_wnv")), f(ref(m, "random", key + "_wvpn")), f(ref(m, "random", key + "_cross")),
                         sg(ref(m, "random", key + "_gap")), sg(ref(m, "grouped10", key + "_gap"))])
    D.table("Family-level agreement under four aggregation rules", [3226, 1000, 950, 950, 900, 1000, 1000], rows,
            note="Within, cross and Δ are means over the 11 flow-level random half-split repeats (Section IV-D); the last column uses the cluster-grouped design with about ten flows per cluster. The alternative grouping moves total_fiat and total_biat from the directional family into a duration-and-totals family. Clusters come from average-linkage clustering of 1 − |ρ_{S}| on training data, cut at 0.2.")

def consequence(D):
    D.h1("VIII. CONSEQUENCE TESTS")
    T = lambda m, a, b: P2[f"transfer_{m}_{a}_to_{b}"]
    D.h2("A. Direct Model Transfer")
    D.p(f"Models do not carry over between contexts (Fig. 8a). The Non-VPN XGBoost model reaches {f(T('XGB','novpn','vpn')['f1'])} macro F1 on VPN test flows, against {f(T('XGB','vpn','vpn')['f1'])} for the VPN model, and the VPN model reaches {f(T('XGB','vpn','novpn')['f1'])} on Non-VPN flows, against {f(T('XGB','novpn','novpn')['f1'])}. Random Forest gives {f(T('RF','novpn','vpn')['f1'])} and {f(T('RF','vpn','novpn')['f1'])}. BROWSING keeps the highest recall ({f(T('XGB','novpn','vpn')['recall'][0],2)} and {f(T('XGB','vpn','novpn')['recall'][0],2)} for XGBoost), and VOIP transfers well only from VPN to Non-VPN ({f(T('XGB','vpn','novpn')['recall'][6],2)}, against {f(T('XGB','novpn','vpn')['recall'][6],2)} in the other direction). CHAT, FT and P2P recall falls to {f(min(T('XGB','novpn','vpn')['recall'][1], T('XGB','novpn','vpn')['recall'][2], T('XGB','novpn','vpn')['recall'][4]),2)}–{f(max(T('XGB','novpn','vpn')['recall'][1], T('XGB','novpn','vpn')['recall'][2], T('XGB','novpn','vpn')['recall'][4]),2)} for the Non-VPN XGBoost model on VPN data. These scores are comparable to, or below, those of the cluster-grouped cross-validation of Section III-C (0.47–0.64), so the two contexts differ at least as much in the feature-to-label mapping as distant clusters of one context do. For the practical question that motivates the study, the answer is clear: a classifier trained on one context needs retraining on the other.")
    D.h2("B. Transfer of a SHAP-Selected Feature List")
    agg = TK.groupby(["model", "target", "k"]).agg(shared=("shared", "mean"), d=("diff", "mean"), lo=("diff", "min"), hi=("diff", "max")).reset_index()
    A = lambda m, c, k: agg[(agg.model == m) & (agg.target == c) & (agg.k == k)].iloc[0]
    k10 = TK[(TK.k == 10)]
    ci = {(r.model, r.target): eval(r.ci_diff) for r in k10[k10.seed == 0].itertuples()}
    D.p(f"Reusing the other context's feature list costs much less. Own and transferred lists share 3 of 5 features at k = 5, {f(agg[agg.k==10].shared.min(),1)}–{f(agg[agg.k==10].shared.max(),1)} of 10 at k = 10 and 14–15 of 15 at k = 15 (means over five selection seeds), so each contrast rests on the features that differ. At k = 10 the own-minus-transferred difference in macro F1, averaged over seeds, is {sg(A('RF','novpn',10).d)} and {sg(A('RF','vpn',10).d)} for Random Forest (Non-VPN and VPN targets) and {sg(A('XGB','novpn',10).d)} and {sg(A('XGB','vpn',10).d)} for XGBoost (Table XI). The VPN Random Forest contrast is a measurable cost: it is positive for all five seeds (range {sg(A('RF','vpn',10).lo)} to {sg(A('RF','vpn',10).hi)}), and its paired interval for the first seed, [{f(ci[('RF','vpn')][0])}, {f(ci[('RF','vpn')][1])}], excludes zero. The XGBoost VPN contrast is also positive for every seed but smaller ({sg(A('XGB','vpn',10).lo)} to {sg(A('XGB','vpn',10).hi)}), and its interval includes zero. For the Non-VPN targets the transferred list does as well or better: the Random Forest contrast is negative for every seed ({sg(A('RF','novpn',10).lo)} to {sg(A('RF','novpn',10).hi)}), and the XGBoost contrast changes sign across seeds.")
    D.p(f"The size of the cost depends on k. At k = 15 every contrast lies within {f(max(abs(agg[agg.k==15].lo).max(), abs(agg[agg.k==15].hi).max()))} of zero, because the lists differ by at most one feature. At k = 5 the contrasts are larger and of either sign: {sg(A('RF','vpn',5).d)} for the VPN Random Forest, but {sg(A('RF','novpn',5).d)} and {sg(A('XGB','novpn',5).d)} for the Non-VPN targets, where the transferred list does better. A shorter list exposes the ranking disagreement more, but not always in the direction of a cost.")
    rnd = {(m, c): P2[f"random10_{m}_{c}"] for m in ("RF", "XGB") for c in ("novpn", "vpn")}
    beat = k10.groupby(["model", "target"])[["own_pct_random", "tr_pct_random"]].mean()
    D.p(f"The controls show that SHAP-based selection itself matters. The bottom-10 lists reach {f(k10.bottom10.min(),2)}–{f(k10.bottom10.max(),2)} macro F1, and the 20 random 10-feature lists average {f(min(v['mean'] for v in rnd.values()),3)}–{f(max(v['mean'] for v in rnd.values()),3)}. Own Top-10 lists beat {N.pct(beat.own_pct_random.min(),0)}–{N.pct(beat.own_pct_random.max(),0)}% of the random lists and transferred lists {N.pct(beat.tr_pct_random.min(),0)}–{N.pct(beat.tr_pct_random.max(),0)}% (means over seeds; Table XI). A ranking learned in the other context is thus a reasonable guide to which features to keep, even though the model built on those features must be retrained.")
    rows = [["Target / model", "Shared\nk = 5/10/15", "Δ k = 5\nmean [min, max]", "Δ k = 10\nmean [min, max]", "Δ k = 15\nmean", "Δ k = 10, seed 1\n95% interval", "Bottom-10", "Random-10\nmean [min, max]", "Beat random\nown / transferred"]]
    for c in ("novpn", "vpn"):
        for m in ("RF", "XGB"):
            a5, a10, a15 = A(m, c, 5), A(m, c, 10), A(m, c, 15)
            rows.append([f"{CTXN[c]} / {m}", f"{f(a5.shared,1)} / {f(a10.shared,1)} / {f(a15.shared,1)}",
                         f"{sg(a5.d)}\n[{sg(a5.lo)}, {sg(a5.hi)}]", f"{sg(a10.d)}\n[{sg(a10.lo)}, {sg(a10.hi)}]", sg(a15.d),
                         f"[{f(ci[(m,c)][0])}, {f(ci[(m,c)][1])}]", f(k10[(k10.model == m) & (k10.target == c)].bottom10.mean()),
                         f"{f(rnd[(m,c)]['mean'])}\n[{f(rnd[(m,c)]['min'])}, {f(rnd[(m,c)]['max'])}]",
                         f"{N.pct(beat.loc[(m,c),'own_pct_random'],0)}% / {N.pct(beat.loc[(m,c),'tr_pct_random'],0)}%"])
    D.table("Transfer of SHAP-selected Top-k feature lists (macro F1 on the untouched test partitions)", [1350, 1000, 1150, 1150, 750, 1150, 750, 1076, 1100], rows,
            note="Δ is macro F1 of the own list minus that of the transferred list, so positive values are a cost of transfer; means, minima and maxima are over five inner-split selection seeds. The interval is a 3,000-draw class-stratified paired bootstrap over test records for the first seed, with models fixed. Bottom-10 is the mean over seeds of the ten lowest-ranked features of the target selector. The 20 random 10-feature lists are drawn once and shared by every model and target; the last column gives the share of them that the own and transferred Top-10 lists beat, averaged over seeds.")
    D.figure(FIG / "fig8_consequence.png", "Consequences of the cross-context differences. (a) Macro F1 of models applied to their own context and to the other context. (b) Own-minus-transferred macro F1 for Top-k feature lists; grey points are the five selection seeds and black markers their mean. Positive values favour the own list.")

def sensitivity(D):
    D.h1("IX. SENTINEL AND ROBUSTNESS CHECKS")
    s = lambda m, c, k: P3[f"sent_{m}_{c}_{k}"]
    w = [s(m, c, "S1vsS2")["rho"] for m in ("RF", "XGB") for c in ("novpn", "vpn")]
    D.p(f"Table XII collects the sensitivity checks. The two sentinel encodings differ in macro F1 by at most {f(max(abs(s(m,c,'S1')['f1']-s(m,c,'S2')['f1']) for m in ('RF','XGB') for c in ('novpn','vpn')),4)}, and within one context they rank the 23 original features at ρ = {f(min(w))}–{f(max(w))}. Random Forest gives the indicators {s('RF','novpn','S1')['ind_share']:.2f}% (S1) and {s('RF','novpn','S2')['ind_share']:.2f}% (S2) of total importance on Non-VPN data and {s('RF','vpn','S1')['ind_share']:.2f}% and {s('RF','vpn','S2')['ind_share']:.2f}% on VPN data; XGBoost gives them at most {max(s('XGB',c,k)['ind_share'] for c in ('novpn','vpn') for k in ('S1','S2')):.2f}%. These numbers describe how the models allocate importance, not how much information missingness carries.")
    D.p(f"How large is the encoding effect? The S1-versus-S2 disagreement, 1 − ρ = {f(1-max(w),2)}–{f(1-min(w),2)}, is about 1.5 to 4 times smaller than the cross-context disagreement on the primary split (1 − ρ = {f(1-P1['cross_RF']['rho'],2)}–{f(1-P1['cross_XGB']['rho'],2)}). It is close to the disagreement between random halves of one context (1 − ρ = {f(1-max(ref(m,'random',k) for m in ('RF','XGB') for k in ('rho_wnv','rho_wvpn')),2)}–{f(1-min(ref(m,'random',k) for m in ('RF','XGB') for k in ('rho_wnv','rho_wvpn')),2)}), which is the more relevant comparison: changing the encoding of undefined statistics moves a ranking about as much as retraining on a different half of the data. The previous version's statement that encoding moves rankings almost as much as the change of context overstated this. Cross-context agreement under the alternative encodings stays close to the primary values: ρ = {f(P3['sent_RF_cross_S1']['rho'],4)} under both S1 and S2 for Random Forest, and {f(P3['sent_XGB_cross_S1']['rho'],4)} (S1) and {f(P3['sent_XGB_cross_S2']['rho'],4)} (S2) for XGBoost. We recomputed the identical Random Forest values from the saved rankings; the two rankings differ (Kendall τ_{{b}} {f(P3['sent_RF_cross_S1']['tau'],4)} and {f(P3['sent_RF_cross_S2']['tau'],4)}, Top-5 overlap {P3['sent_RF_cross_S1']['top5']} and {P3['sent_RF_cross_S2']['top5']}), but their squared rank differences happen to sum to the same total.")
    rob = lambda m, k: P3[f"rob_{m}_{k}"]
    pvi = [P3[f"rob_{m}_{c}_path_vs_interv"] for m in ("RF", "XGB") for c in ("novpn", "vpn")]
    D.p(f"Across the six model and TreeSHAP configurations explained on 500 records, cross-context ρ ranges from {f(min(rob(m,k)['rho'] for m in ('RF','XGB','ET') for k in ('path','interv')))} to {f(max(rob(m,k)['rho'] for m in ('RF','XGB','ET') for k in ('path','interv')))}, and three of five leading features are shared in all six. Within one model and context, path-dependent and interventional rankings agree at ρ = {f(min(pvi))}–{f(max(pvi))}. Extra Trees agrees less well with the path-dependent Random Forest ({f(min(P3[f'rob_ET_vs_RF_{c}_{k}'] for c in ('novpn','vpn') for k in ('path','interv')))}–{f(max(P3[f'rob_ET_vs_RF_{c}_{k}'] for c in ('novpn','vpn') for k in ('path','interv')))}). Refitting XGBoost with three other seeds gives mean within-context ρ of {f(P3['seed_XGB_novpn'],4)} (Non-VPN) and {f(P3['seed_XGB_vpn'],4)} (VPN), so seed noise alone is small, and max_depth = 3 or 10 leaves cross-context ρ at {f(P3['hp_XGB_depth3']['cross']['rho'])} and {f(P3['hp_XGB_depth10']['cross']['rho'])}. The bootstrap intervals over explained records are biased upward, because resampling smooths both importance profiles; Table XII gives the bias-corrected basic intervals.")
    rows = [["Configuration", "Macro F1\nNV / VPN", "Cross-context ρ", "95% interval\n(explained records)", "RBO", "Top-5"]]
    def row(lab, f1, d, ci="—"):
        rows.append([lab, f1, f(d["rho"], 4), ci, f(d["rbo"]), f"{d['top5']}/5"])
    B = lambda m, c: P1[f"base_{m}_{c}"]["f1"]
    rows.append({"section": "Primary fits and sentinel encodings (full test partitions)"})
    for m in ("RF", "XGB"):
        row(f"{m}, raw sentinel (primary)", f"{f(B(m,'novpn'))} / {f(B(m,'vpn'))}", P1[f"cross_{m}"])
        for k in ("S1", "S2"):
            row(f"{m}, {k}", f"{f(s(m,'novpn',k)['f1'])} / {f(s(m,'vpn',k)['f1'])}", P3[f"sent_{m}_cross_{k}"])
    rows.append({"section": "Model and TreeSHAP formulation (500 explained records per context)"})
    MN2 = {"RF": "Random Forest", "XGB": "XGBoost", "ET": "Extra Trees"}
    for m in ("RF", "XGB", "ET"):
        pf = P3[f"rob_perf_{m}_novpn"]["f1"], P3[f"rob_perf_{m}_vpn"]["f1"]
        for k, kl in (("path", "path-dependent"), ("interv", "interventional")):
            d = rob(m, k)
            row(f"{MN2[m]}, {kl}", f"{f(pf[0])} / {f(pf[1])}", d, f"[{f(d['ci_basic'][0])}, {f(d['ci_basic'][1])}]")
    rows.append({"section": "XGBoost hyperparameters (full test partitions)"})
    for k, kl in (("depth3", "max_depth = 3"), ("depth10", "max_depth = 10")):
        h = P3[f"hp_XGB_{k}"]; row(f"XGBoost, {kl}", f"{f(h['f1']['novpn'])} / {f(h['f1']['vpn'])}", h["cross"])
    D.table("Sensitivity of cross-context agreement to sentinel encoding, model, TreeSHAP formulation and hyperparameters", [2900, 1350, 1250, 1600, 900, 1026], rows,
            note="S1 keeps −1 and appends ten undefined-value indicators; S2 replaces −1 by NaN and appends the same indicators; agreement is computed over the 23 original features. Intervals are bias-corrected basic intervals from 2,000 resamples of the explained records within each context, with models and backgrounds fixed; they exclude training, background and session-level uncertainty.")
